import{_ as t,o as s,c as a,ao as n}from"./chunks/framework.DOMnz-Zz.js";const g=JSON.parse('{"title":"A second frontend","description":"","frontmatter":{},"headers":[],"relativePath":"guide/second-frontend.md","filePath":"guide/second-frontend.md","lastUpdated":null}'),o={name:"guide/second-frontend.md"};function i(d,e,r,h,l,c){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="A-second-frontend" tabindex="-1">A second frontend <a class="header-anchor" href="#A-second-frontend" aria-label="Permalink to &quot;A second frontend {#A-second-frontend}&quot;">​</a></h1><p>The backend owns the project state — sessions, kernels, file watching — and the frontend renders what it is sent. So a desktop and a laptop can attach to the <strong>same backend at once</strong> and see the same sessions, the same work-state colours and the same REPLs.</p><h2 id="Add-one" tabindex="-1">Add one <a class="header-anchor" href="#Add-one" aria-label="Permalink to &quot;Add one {#Add-one}&quot;">​</a></h2><p>On the second machine, install the frontend role against the same backend SSH alias:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/kalidke/ship-of-tools/main/scripts/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myserver</span></span></code></pre></div><p>(On Windows, use the release zip and <code>scripts\\install-shortcut.ps1</code>; see <a href="./../start/install">Install</a>.) Launch it with <code>sot-launch</code>; it spawns its own <code>ssh</code> child and connects as one more client of the daemon. Nothing on the server changes.</p><h2 id="What-is-shared-and-what-is-not" tabindex="-1">What is shared and what is not <a class="header-anchor" href="#What-is-shared-and-what-is-not" aria-label="Permalink to &quot;What is shared and what is not {#What-is-shared-and-what-is-not}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Shared (lives on the backend)</th><th style="text-align:right;">Per frontend</th></tr></thead><tbody><tr><td style="text-align:right;">sessions and their agents</td><td style="text-align:right;">window layout and which pane has focus</td></tr><tr><td style="text-align:right;">each workspace&#39;s Julia kernel and REPL</td><td style="text-align:right;">the active session and cursor positions</td></tr><tr><td style="text-align:right;">work-state colours and comm messages</td><td style="text-align:right;">the Terminal drawer (a shell on <em>that</em> machine)</td></tr><tr><td style="text-align:right;">files and previews</td><td style="text-align:right;"><code>settings.toml</code> (layout preset, GPU preference)</td></tr></tbody></table><p>Closing one frontend affects nothing the other sees: the agents run under the backend&#39;s own supervisors, not under any frontend.</p><h2 id="Where-a-session&#39;s-output-lands" tabindex="-1">Where a session&#39;s output lands <a class="header-anchor" href="#Where-a-session&#39;s-output-lands" aria-label="Permalink to &quot;Where a session&#39;s output lands {#Where-a-session&#39;s-output-lands}&quot;">​</a></h2><p>With two windows attached, a file an agent shows (<code>sot-fe preview</code>, <code>show-result</code>) reaches the preview pane and the badge of <strong>every</strong> window. A browser an agent opens (a docs site, a URL, a <code>wglshow</code> figure) opens on <strong>one</strong> computer: the window you used last, however long ago; with none used yet, the one that connected last. A window counts as used from its second key press, click or wheel step within five minutes, and a switch between windows is noticed within about six seconds. Name a window with <code>--fe &lt;host&gt;</code> to override this. A window that is reconnecting at that moment is not chosen, and a browser open cannot wait for it.</p><h2 id="Many-machines,-one-workspace" tabindex="-1">Many machines, one workspace <a class="header-anchor" href="#Many-machines,-one-workspace" aria-label="Permalink to &quot;Many machines, one workspace {#Many-machines,-one-workspace}&quot;">​</a></h2><p>To make a server reachable from every frontend in a fleet — not only the one you installed it from — enrol it on the hub: see <a href="./enrolling">Enrolling a host</a>.</p>',13)])])}const u=t(o,[["render",i]]);export{g as __pageData,u as default};
